import { stopAudio } from './audio.mjs';
import { pauseLessonAudio } from './lesson_audio.mjs';
const BASE=new URL('./audio/words/',import.meta.url);
const STORE='english-quest-word-mp3-v1';
const tierNames={elem_1000:'國小',jhs_2000:'國中',shs_3000:'高中',toeic:'TOEIC',toefl:'TOEFL',sat:'SAT',gre:'GRE',gmat:'GMAT'};
let manifest=null,loading=null,loadError='',selected='elementary-001',autoNext=false,rate=1;
let cues=null,cueLoading='',cueError='',resumeTime=0;
let lastSave=0,resumePlaying=false;
const cache=new Map();
try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');if(saved&&/^(elementary|junior|senior|toeic|toefl|sat|gre|gmat)-\d{3}$/.test(saved.group)){selected=saved.group;resumeTime=Number.isFinite(saved.time)&&saved.time>=0?saved.time:0;}if([.75,1,1.25,1.5].includes(saved?.rate))rate=saved.rate;}catch{}
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const formatDuration=seconds=>`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
export function wordAudioRoute(){return '#wordaudio/'+selected;}
export function setWordAudioGroup(id){if(/^(elementary|junior|senior|toeic|toefl|sat|gre|gmat)-\d{3}$/.test(id||'')&&selected!==id){selected=id;cues=null;resumeTime=0;}}
function save(player){if(player?.dataset.mp3Group&&player.dataset.mp3Group!==selected)return;try{localStorage.setItem(STORE,JSON.stringify({group:selected,time:player?.currentTime||0,rate}));}catch{const note=document.querySelector('#mp3-save-note');if(note)note.textContent='無法保存播放位置，仍可播放與下載。';}}
function load(render){if(loading)return;loadError='';loading=fetch(new URL('manifest.json',BASE)).then(r=>{if(!r.ok)throw Error('manifest');return r.json();}).then(m=>{if(m.version!==1||!Array.isArray(m.groups)||!m.groups.length)throw Error('manifest');manifest=m;if(!m.groups.some(g=>g.id===selected)){selected=m.groups[0].id;resumeTime=0;}render();}).catch(()=>{loadError='目前無法載入音檔目錄，請重試。';loading=null;render();});}
function wordListHtml(words,start){return `<ol class="mp3-word-list" start="${start}">${words.map((w,i)=>`<li data-mp3-word="${i}"><button type="button" data-mp3-seek="${i}" aria-label="播放 ${e(w.en)}，${e(w.zh)}"><span lang="en">${e(w.en)}</span><span>${e(w.zh)}</span><small>${formatDuration(w.start)} →</small></button></li>`).join('')}</ol>`;}
function loadCues(group,render){if(cache.has(group.id)){cues=cache.get(group.id);return;}if(cueLoading===group.id)return;cueLoading=group.id;cueError='';fetch(new URL(group.id+'.json',BASE)).then(r=>{if(!r.ok)throw Error('cue');return r.json();}).then(data=>{if(data.id!==group.id||!Array.isArray(data.words)||data.words.length!==group.wordCount)throw Error('cue');cache.set(group.id,data.words);if(selected===group.id){cues=data.words;cueLoading='';const container=document.querySelector('#mp3-word-list-container');if(container)container.innerHTML=wordListHtml(cues,group.start);}}).catch(()=>{if(selected===group.id){cueError='單字時間表載入失敗。音檔仍可播放或下載。';cueLoading='';const container=document.querySelector('#mp3-word-list-container');if(container)container.innerHTML='<p role="status">'+e(cueError)+'</p><button class="btn" data-mp3-cues-retry>重載單字表</button>';}});}
function tierButtons(entries,current){return entries.map(([tier,label])=>`<button type="button" class="btn ${tier===current.tier?'primary':'quiet'}" data-mp3-tier="${tier}" aria-pressed="${tier===current.tier}">${label} · ${manifest.groups.filter(g=>g.tier===tier).reduce((n,g)=>n+g.wordCount,0).toLocaleString()} 字</button>`).join('');}
export function renderWordAudio(render=()=>{}){
 if(!manifest){if(!loadError)load(render);return `<section class="word-mp3"><h1>單字 MP3 播放練習</h1><p role="status">${loadError||'正在載入 MP3 音檔目錄…'}</p>${loadError?'<button class="btn" data-mp3-retry>重新載入</button>':''}</section>`;}
 const current=manifest.groups.find(g=>g.id===selected)||manifest.groups[0];
 selected=current.id;loadCues(current,render);
 const groups=manifest.groups.filter(g=>g.tier===current.tier);
 const url=new URL(current.file,BASE).href;
 return `<article class="lesson-page word-mp3"><header><p class="pill">真正的 MP3 音檔 · 每 50 字一組</p><h1>聽單字，也留時間跟著念</h1><p>每一個字：<strong>英文一次 → 中文一次，連續重複三輪</strong>，再進入下一個字。國小、國中、高中及考試詞彙共 ${manifest.totalWords.toLocaleString()} 張字卡、${manifest.totalGroups} 組。</p><p class="small">使用美式英文與臺灣華語合成語音。學段沿用既有字卡分類，中文會朗讀本卡全部釋義。</p></header>
 <section class="card"><h2>1. 選學段與單字組</h2><div class="mp3-tier-buttons">${tierButtons(Object.entries(tierNames).slice(0,3),current)}</div>${manifest.groups.some(g=>!['elem_1000','jhs_2000','shs_3000'].includes(g.tier))?`<details class="mp3-exam-tiers" ${!['elem_1000','jhs_2000','shs_3000'].includes(current.tier)?'open':''}><summary>其他字卡：TOEIC、TOEFL、SAT、GRE、GMAT</summary><div class="mp3-tier-buttons">${tierButtons(Object.entries(tierNames).slice(3).filter(([tier])=>manifest.groups.some(g=>g.tier===tier)),current)}</div></details>`:''}<div></div><label for="mp3-group">${tierNames[current.tier]}每 50 字一組</label><select id="mp3-group">${groups.map(g=>`<option value="${g.id}" ${g.id===selected?'selected':''}>第 ${Math.ceil(g.start/50)} 組 · ${g.start}–${g.end} 字 · ${formatDuration(g.duration)}</option>`).join('')}</select><p>${groups.length} 組可選；目前第 ${Math.ceil(current.start/50)} 組。</p></section>
 <section class="card mp3-player-card"><h2>2. 播放與跟讀</h2><p><strong>${tierNames[current.tier]} · 第 ${Math.ceil(current.start/50)} 組 · ${current.start}–${current.end} 字</strong><br>${formatDuration(current.duration)} · ${(current.bytes/1e6).toFixed(1)} MB</p><audio id="word-mp3-player" data-mp3-group="${e(current.id)}" controls preload="none" src="${e(url)}" aria-label="${tierNames[current.tier]}第 ${Math.ceil(current.start/50)} 組雙語三輪單字 MP3">此瀏覽器不支援音訊播放，請使用下方下載連結。</audio><p id="mp3-now" class="mp3-now">${resumeTime>0?'上次停在 '+formatDuration(resumeTime)+'，按播放接續。':'按播放開始，或點選下方單字跳轉。'}</p><p id="mp3-status" role="status"></p><div class="mp3-options"><label for="mp3-speed">播放速度</label><select id="mp3-speed">${[.75,1,1.25,1.5].map(n=>`<option value="${n}" ${rate===n?'selected':''}>${n} 倍</option>`).join('')}</select><label><input type="checkbox" id="mp3-auto-next" ${autoNext?'checked':''}>播完自動接下一組</label></div><div class="learning-actions"><a class="btn" href="${e(url)}" download="${e(current.file)}">下載本組 MP3</a><a class="btn quiet" href="#flashcards">回字卡核對例句</a></div><p class="small" id="mp3-save-note">播放位置會保存在此瀏覽器。下載後可離線播放；首次線上播放需要載入音檔。</p></section>
 <section class="card"><h2>3. 本組單字與播放位置</h2><p>點單字從該字第一輪開始。跟讀後遮住中文，試著說出意思。</p><div id="mp3-word-list-container">${cues?wordListHtml(cues,current.start):`<p role="status">${cueError||'正在載入本組單字…'}</p>${cueError?'<button class="btn" data-mp3-cues-retry>重載單字表</button>':''}`}</div></section></article>`;
}
export function prepareWordAudio(root){const player=root.querySelector('#word-mp3-player');if(player&&player.dataset.mp3Group===selected){if(player.readyState>0)resumeTime=player.currentTime;resumePlaying=!player.paused;}}
export function stopWordAudio(root=document){const player=root.querySelector('#word-mp3-player');if(player){save(player);player.pause();}}
function selectGroup(id,render){const group=manifest?.groups.find(g=>g.id===id);if(!group)return;stopWordAudio();selected=id;resumeTime=0;cues=null;cueLoading='';cueError='';save(null);history.replaceState(null,'',location.pathname+location.search+wordAudioRoute());render();}
export function handleWordAudioClick(button,render){const d=button.dataset;if('mp3Retry' in d){loadError='';load(render);render();return true;}if('mp3CuesRetry' in d){cueError='';cueLoading='';const group=manifest?.groups.find(g=>g.id===selected);const container=document.querySelector('#mp3-word-list-container');if(container)container.innerHTML='<p role="status">正在載入本組單字…</p>';if(group)loadCues(group,render);return true;}if(d.mp3Tier){selectGroup(manifest?.groups.find(g=>g.tier===d.mp3Tier)?.id,render);return true;}if(d.mp3Seek!==undefined){const i=Number(d.mp3Seek),word=Number.isInteger(i)&&cues?.[i],player=document.querySelector('#word-mp3-player');if(word&&player){resumeTime=word.start;player.currentTime=word.start;player.play().catch(()=>{document.querySelector('#mp3-status').textContent='請按音訊控制列的播放鍵開始。';});}return true;}return false;}
export function handleWordAudioChange(target,render){if(target.id==='mp3-group'){selectGroup(target.value,render);return true;}if(target.id==='mp3-speed'){const n=Number(target.value);if([.75,1,1.25,1.5].includes(n)){rate=n;const player=document.querySelector('#word-mp3-player');if(player){player.playbackRate=rate;save(player);}}return true;}if(target.id==='mp3-auto-next'){autoNext=target.checked;return true;}return false;}
export function bindWordAudio(root,render){const player=root.querySelector('#word-mp3-player');if(!player)return;player.playbackRate=rate;
 player.addEventListener('loadedmetadata',()=>{if(root.querySelector('#word-mp3-player')!==player)return;if(resumeTime>0&&resumeTime<player.duration)player.currentTime=resumeTime;resumeTime=0;if(resumePlaying){resumePlaying=false;player.play().catch(()=>{});}});
 player.addEventListener('play',()=>{if(root.querySelector('#word-mp3-player')!==player)return;stopAudio();pauseLessonAudio();root.querySelector('#mp3-status').textContent='';});
 player.addEventListener('error',()=>{if(root.querySelector('#word-mp3-player')!==player)return;root.querySelector('#mp3-status').textContent='音檔暫時無法播放，請重載頁面或嘗試下載。';});
 player.addEventListener('pause',()=>save(player));
 player.addEventListener('timeupdate',()=>{if(root.querySelector('#word-mp3-player')!==player)return;const time=player.currentTime;let index=cues?.findIndex(w=>time>=w.start&&time<w.end)??-1;const word=cues?.[index];root.querySelectorAll('[data-mp3-word]').forEach(el=>{el.classList.toggle('is-playing',Number(el.dataset.mp3Word)===index);});if(word){const round=word.repetitions.filter(r=>r.en<=time).at(-1);root.querySelector('#mp3-now').textContent=`${word.en} · ${word.zh} · 第 ${round?.round||1} / 3 輪`;}if(Math.abs(time-lastSave)>5){save(player);lastSave=time;}});
 player.addEventListener('ended',()=>{if(root.querySelector('#word-mp3-player')!==player)return;save(player);if(!autoNext)return;const current=manifest.groups.findIndex(g=>g.id===selected),next=manifest.groups[current+1];if(next&&next.tier===manifest.groups[current].tier){selectGroup(next.id,render);root.querySelector('#word-mp3-player')?.play().catch(()=>{const status=root.querySelector('#mp3-status');if(status)status.textContent='下一組已準備好，請按播放繼續。';});}else root.querySelector('#mp3-status').textContent='這個學段已播放到最後一組。';});
}
